#!/usr/bin/env bash
# Eval runner. Scores each dimension that has a working engine:
#   - normalization (raw → match_text, §7) — LIVE, scored below against the
#     hand-labelled datasets/normalization set.
#   - matching (raw → ingredient / band, §6) — the calibration set is built
#     (datasets/matching, generated by gen_matching_cases.ts), but scoring waits
#     on the server-side cascade (roadmap step 8).
set -euo pipefail
here="$(dirname "$0")"

deno run --allow-read "$here/score_normalization.ts"

matching="$here/../datasets/matching/cases.jsonl"
n=$(grep -c '' "$matching" || true)
echo "matching/band: $n calibration cases ready; engine not implemented yet" \
     "(roadmap step 8) — not scored."
